import{_ as o,a0 as l,w as p,s as d,ao as r,I as t,x as i,a1 as s,A as a}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const y=JSON.parse('{"title":"優化 MySQL： 3 個簡單的小調整 | LCTT x X-CMD","titleTemplate":false,"description":"優化 MySQL： 3 個簡單的小調整 | LCTT (201802) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"優化 MySQL： 3 個簡單的小調整 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"優化 MySQL： 3 個簡單的小調整 | LCTT (201802) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201802/20180202 Tuning MySQL 3 Simple Tweaks","title":"優化 MySQL： 3 個簡單的小調整","tag":"201802","desc":""},"relativePath":"201802/20180202 Tuning MySQL 3 Simple Tweaks.md","filePath":"[post].md"}'),h={name:"201802/20180202 Tuning MySQL 3 Simple Tweaks.md"};function b(u,e,m,g,f,c){const n=l("Link");return p(),d("div",null,[e[13]||(e[13]=r('<h1 id="優化-mysql-3-個簡單的小調整" tabindex="-1">優化 MySQL： 3 個簡單的小調整 <a class="header-anchor" href="#優化-mysql-3-個簡單的小調整" aria-label="Permalink to “優化 MySQL： 3 個簡單的小調整”">​</a></h1><p>如果你不改變 MySQL 的缺省配置，你的服務器的性能就像下圖的壞在一檔的法拉利一樣 “虎落平陽被犬欺” …</p><p><img src="https://cdn-images-1.medium.com/max/1000/1*b7M28XbrOc4FF3tJP-vvyg.png" alt=""></p><p>我並不期望成為一個專家級的 DBA，但是，在我優化 MySQL 時，我推崇 80/20 原則，明確説就是通過簡單的調整一些配置，你可以壓榨出高達 80% 的性能提升。尤其是在服務器資源越來越便宜的當下。</p><h3 id="警告" tabindex="-1">警告 <a class="header-anchor" href="#警告" aria-label="Permalink to “警告”">​</a></h3><ol><li>沒有兩個資料庫或者應用程序是完全相同的。這裏假設我們要調整的資料庫是為一個“典型”的 Web 網站服務的，優先考慮的是快速查詢、良好的用户體驗以及處理大量的流量。</li><li>在你對服務器進行優化之前，請做好資料庫備份！</li></ol><h3 id="_1、-使用-innodb-存儲引擎" tabindex="-1">1、 使用 InnoDB 存儲引擎 <a class="header-anchor" href="#_1、-使用-innodb-存儲引擎" aria-label="Permalink to “1、 使用 InnoDB 存儲引擎”">​</a></h3><p>如果你還在使用 MyISAM 存儲引擎，那麼是時候轉換到 InnoDB 了。有很多的理由都表明 InnoDB 比 MyISAM 更有優勢，如果你關注性能，那麼，我們來看一下它們是如何利用物理內存的：</p><ul><li>MyISAM：僅在內存中保存索引。</li><li>InnoDB：在內存中保存索引<strong>和</strong>數據。</li></ul><p>結論：保存在內存的內容訪問速度要比磁盤上的更快。</p><p>下面是如何在你的表上去轉換存儲引擎的命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ALTER TABLE table_name ENGINE=InnoDB;</span></span></code></pre></div><p><em>注意：你已經創建了所有合適的索引，對嗎？為了更好的性能，創建索引永遠是第一優先考慮的事情。</em></p><h3 id="_2、-讓-innodb-使用所有的內存" tabindex="-1">2、 讓 InnoDB 使用所有的內存 <a class="header-anchor" href="#_2、-讓-innodb-使用所有的內存" aria-label="Permalink to “2、 讓 InnoDB 使用所有的內存”">​</a></h3><p>你可以在 <code>my.cnf</code> 文件中編輯你的 MySQL 配置。使用 <code>innodb_buffer_pool_size</code> 參數去配置在你的服務器上允許 InnoDB 使用物理內存數量。</p><p>對此（假設你的服務器_僅僅_運行 MySQL），公認的“經驗法則”是設置為你的服務器物理內存的 80%。在保證操作系統不使用交換分區而正常運行所需要的足夠內存之後 ，儘可能多地為 MySQL 分配物理內存。</p><p>因此，如果你的服務器物理內存是 32 GB，可以將那個參數設置為多達 25 GB。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>innodb_buffer_pool_size = 25600M</span></span></code></pre></div><p>*注意：（1）如果你的服務器內存較小並且小於 1 GB。為了適用本文的方法，你應該去升級你的服務器。 （2） 如果你的服務器內存特別大，比如，它有 200 GB，那麼，根據一般常識，你也沒有必要為操作系統保留多達 40 GB 的內存。 *</p><h3 id="_3、-讓-innodb-多任務運行" tabindex="-1">3、 讓 InnoDB 多任務運行 <a class="header-anchor" href="#_3、-讓-innodb-多任務運行" aria-label="Permalink to “3、 讓 InnoDB 多任務運行”">​</a></h3><p>如果服務器上的參數 <code>innodb_buffer_pool_size</code> 的配置是大於 1 GB，將根據參數 <code>innodb_buffer_pool_instances</code> 的設置， 將 InnoDB 的緩衝池劃分為多個。</p><p>擁有多於一個的緩衝池的好處有：</p><blockquote><p>在多線程同時訪問緩衝池時可能會遇到瓶頸。你可以通過啓用多緩衝池來最小化這種爭用情況：</p></blockquote><p>對於緩衝池數量的官方建議是：</p><blockquote><p>為了實現最佳的效果，要綜合考慮 <code>innodb_buffer_pool_instances</code> 和 <code>innodb_buffer_pool_size</code> 的設置，以確保每個實例至少有不小於 1 GB 的緩衝池。</p></blockquote><p>因此，在我們的示例中，將參數 <code>innodb_buffer_pool_size</code> 設置為 25 GB 的擁有 32 GB 物理內存的服務器上。一個合適的設置為 25600M / 24 = 1.06 GB</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>innodb_buffer_pool_instances = 24</span></span></code></pre></div><h3 id="注意" tabindex="-1">注意！ <a class="header-anchor" href="#注意" aria-label="Permalink to “注意！”">​</a></h3><p>在修改了 <code>my.cnf</code> 文件後需要重啓 MySQL 才能生效：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo service mysql restart</span></span></code></pre></div><hr><p>還有更多更科學的方法來優化這些參數，但是這幾點可以作為一個通用準則來應用，將使你的 MySQL 服務器性能更好。</p><hr><p>作者簡介:</p><p>我喜歡商業技術以及跑車 | 集團 CTO @ Parcel Monkey， Cloud Fulfilment &amp; Kong。</p><hr>',36)),t("p",null,[e[1]||(e[1]=i("via: ",-1)),s(n,{href:"https://medium.com/@richb_/tuning-mysql-3-simple-tweaks-6356768f9b90"},{default:a(()=>[...e[0]||(e[0]=[i("https://medium.com/@richb_/tuning-mysql-3-simple-tweaks-6356768f9b90",-1)])]),_:1})]),t("p",null,[e[5]||(e[5]=i("作者：",-1)),s(n,{href:"https://medium.com/@richb_"},{default:a(()=>[...e[2]||(e[2]=[i("Rich Barrett",-1)])]),_:1}),e[6]||(e[6]=i(" 譯者：",-1)),s(n,{href:"https://github.com/qhwdw"},{default:a(()=>[...e[3]||(e[3]=[i("qhwdw",-1)])]),_:1}),e[7]||(e[7]=i(" 校對：",-1)),s(n,{href:"https://github.com/wxy"},{default:a(()=>[...e[4]||(e[4]=[i("wxy",-1)])]),_:1})]),t("p",null,[e[10]||(e[10]=i("本文由 ",-1)),s(n,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...e[8]||(e[8]=[i("LCTT",-1)])]),_:1}),e[11]||(e[11]=i(" 原創編譯，",-1)),s(n,{href:"https://linux.cn/"},{default:a(()=>[...e[9]||(e[9]=[i("Linux中國",-1)])]),_:1}),e[12]||(e[12]=i(" 榮譽推出",-1))])])}const T=o(h,[["render",b]]);export{y as __pageData,T as default};
